from datetime import datetime

def basename(p):
    return p.split('/')[-1]

def file_exists(path):
    return apis.file_system.file_exists(file_path=path, access_token=fs_token)['exists']

base_dir='~/photographs/vacations'
rome_dir=f"{base_dir}/Rome"
sant_dir=f"{base_dir}/Santorini"
berl_dir=f"{base_dir}/Berlin"

# Use previously computed file_meta and files_now if available; otherwise rebuild
if 'files_now' not in globals() or 'file_meta' not in globals():
    files_now = apis.file_system.show_directory(directory_path='~/photographs/vacations/', recursive=False, entry_type='files', access_token=fs_token)
    file_meta = {p: apis.file_system.show_file(file_path=p, access_token=fs_token) for p in files_now}

current_year = datetime.now().year
rome_files=[]
santorini_files=[]
berlin_files=[]
for p in files_now:
    info=file_meta[p]
    created_at=info.get('created_at')
    dt = datetime.fromisoformat(created_at.replace('Z','+00:00')) if created_at else None
    if dt and dt.year==current_year and dt.month==3:
        rome_files.append(p)
    elif dt and dt.year==current_year and dt.month==4:
        santorini_files.append(p)
    else:
        berlin_files.append(p)

print('counts', {'Rome':len(rome_files), 'Santorini':len(santorini_files), 'Berlin':len(berlin_files)})

# collision check correct
rome_coll=[]
for src in rome_files:
    dest=f"{rome_dir}/{basename(src)}"
    if file_exists(dest):
        rome_coll.append(dest)

sant_coll=[]
for src in santorini_files:
    dest=f"{sant_dir}/{basename(src)}"
    if file_exists(dest):
        sant_coll.append(dest)

berl_coll=[]
for src in berlin_files:
    dest=f"{berl_dir}/{basename(src)}"
    if file_exists(dest):
        berl_coll.append(dest)

print('collisions', {'Rome':len(rome_coll), 'Santorini':len(sant_coll), 'Berlin':len(berl_coll)})
